begin; set local statement_timeout='30s';create schema cmpri_self_notification_validation;
create table cmpri_self_notification_validation.profiles(id uuid primary key,active boolean default true,role text default 'Chief Engineer',secondary_roles text[] default '{}');
create table cmpri_self_notification_validation.hotel_members(hotel_id uuid,user_id uuid,active boolean default true);
create table cmpri_self_notification_validation.work_orders(id uuid primary key,hotel_id uuid,created_by uuid,submitted_by_user_id uuid,history_actor_user_id uuid,history_source text,notes text);
create table cmpri_self_notification_validation.cmpri_work_order_history(id uuid primary key,hotel_id uuid,work_order_id uuid,actor_user_id uuid,event_type text,recorded_at timestamptz default clock_timestamp());
create table cmpri_self_notification_validation.cmpri_staff_notes(id uuid primary key,hotel_id uuid,author_user_id uuid);
create table cmpri_self_notification_validation.cmpri_room_operation_imports(id uuid primary key,hotel_id uuid,imported_by_user_id uuid);
create table cmpri_self_notification_validation.cmpri_work_order_technician_views(id uuid primary key,hotel_id uuid,technician_user_id uuid);
create table cmpri_self_notification_validation.cmpri_dashboard_notifications(id uuid primary key default gen_random_uuid(),hotel_id uuid,recipient_user_id uuid,actor_user_id uuid,notification_key text,work_order_id uuid,push_requested boolean default true,recorded_at timestamptz default clock_timestamp(),read_at timestamptz,cleared_at timestamptz);
create table cmpri_self_notification_validation.cmpri_web_push_subscriptions(id uuid primary key default gen_random_uuid(),hotel_id uuid,recipient_user_id uuid,enabled boolean default true);
create table cmpri_self_notification_validation.cmpri_web_push_deliveries(hotel_id uuid,recipient_user_id uuid,subscription_id uuid,notification_key text,status text,inbox_id uuid,unique(hotel_id,recipient_user_id,subscription_id,notification_key));
create table cmpri_self_notification_validation.cmpri_event_push_rollout(singleton boolean,activated_at timestamptz);insert into cmpri_self_notification_validation.cmpri_event_push_rollout values(true,'2000-01-01');
insert into cmpri_self_notification_validation.profiles(id) values('00000000-0000-4000-8000-000000000010'),('00000000-0000-4000-8000-000000000012'),('00000000-0000-4000-8000-000000000018');
insert into cmpri_self_notification_validation.hotel_members(hotel_id,user_id) select '00000000-0000-4000-8000-000000000001',id from cmpri_self_notification_validation.profiles;
insert into cmpri_self_notification_validation.cmpri_web_push_subscriptions(hotel_id,recipient_user_id) select '00000000-0000-4000-8000-000000000001',id from cmpri_self_notification_validation.profiles;
__HELPERS__
__CAPTURE__;
create trigger actor_capture before insert or update on cmpri_self_notification_validation.work_orders for each row execute function cmpri_self_notification_validation.cmpri_capture_work_order_history_actor();
__QUEUE__;
create trigger zz_queue after insert on cmpri_self_notification_validation.cmpri_dashboard_notifications for each row execute function cmpri_self_notification_validation.cmpri_queue_dashboard_event_push();
create function cmpri_self_notification_validation.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function cmpri_self_notification_validation.emit(k text, wid uuid default null, actor uuid default null) returns void language sql as $$
 insert into cmpri_self_notification_validation.cmpri_dashboard_notifications(hotel_id,recipient_user_id,notification_key,work_order_id,actor_user_id) select '00000000-0000-4000-8000-000000000001',id,k,wid,actor from cmpri_self_notification_validation.profiles
$$;
insert into cmpri_self_notification_validation.work_orders values('00000000-0000-4000-8000-000000000100','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000010',null,'');
select cmpri_self_notification_validation.emit('work-order-note:00000000-0000-4000-8000-000000000100:1','00000000-0000-4000-8000-000000000100');
select cmpri_self_notification_validation.assert_true((select count(*)=2 from cmpri_self_notification_validation.cmpri_dashboard_notifications where notification_key like 'work-order-note:%'),'note excludes author');
select cmpri_self_notification_validation.assert_true((select count(*)=2 from cmpri_self_notification_validation.cmpri_web_push_deliveries where notification_key like 'work-order-note:%'),'no self push intent');
create function cmpri_self_notification_validation.history_notice() returns trigger language plpgsql as $$begin perform cmpri_self_notification_validation.emit('work-order-status:'||new.id,new.work_order_id);return new;end$$;
create trigger status_notice after insert on cmpri_self_notification_validation.cmpri_work_order_history for each row execute function cmpri_self_notification_validation.history_notice();
insert into cmpri_self_notification_validation.cmpri_work_order_history(id,hotel_id,work_order_id,actor_user_id,event_type) values('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000100','00000000-0000-4000-8000-000000000012','closed');
select cmpri_self_notification_validation.assert_true(not exists(select 1 from cmpri_self_notification_validation.cmpri_dashboard_notifications where notification_key='work-order-status:00000000-0000-4000-8000-000000000101' and recipient_user_id='00000000-0000-4000-8000-000000000012'),'fresh status row actor overrides older context');
select cmpri_self_notification_validation.assert_true(exists(select 1 from cmpri_self_notification_validation.cmpri_dashboard_notifications where notification_key='work-order-status:00000000-0000-4000-8000-000000000101' and recipient_user_id='00000000-0000-4000-8000-000000000010'),'other Chief still notified');
select set_config('cmpri.notification_actor','',true);select set_config('cmpri.notification_hotel','',true);
insert into cmpri_self_notification_validation.cmpri_staff_notes values('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000018');select cmpri_self_notification_validation.emit('staff-note:00000000-0000-4000-8000-000000000101');
select cmpri_self_notification_validation.assert_true(not exists(select 1 from cmpri_self_notification_validation.cmpri_dashboard_notifications where notification_key='staff-note:00000000-0000-4000-8000-000000000101' and recipient_user_id='00000000-0000-4000-8000-000000000018'),'staff-note author excluded');
insert into cmpri_self_notification_validation.cmpri_room_operation_imports values('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000010');select cmpri_self_notification_validation.emit('room-operations:00000000-0000-4000-8000-000000000101');
insert into cmpri_self_notification_validation.cmpri_work_order_technician_views values('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000012');select cmpri_self_notification_validation.emit('technician-view:00000000-0000-4000-8000-000000000101');
select cmpri_self_notification_validation.emit('new-order:00000000-0000-4000-8000-000000000100','00000000-0000-4000-8000-000000000100');
select cmpri_self_notification_validation.assert_true(not exists(select 1 from cmpri_self_notification_validation.cmpri_dashboard_notifications where recipient_user_id='00000000-0000-4000-8000-000000000010' and notification_key in ('new-order:00000000-0000-4000-8000-000000000100','room-operations:00000000-0000-4000-8000-000000000101')),'creation and room operations exclude acting user');
select cmpri_self_notification_validation.assert_true(not exists(select 1 from cmpri_self_notification_validation.cmpri_dashboard_notifications where recipient_user_id='00000000-0000-4000-8000-000000000012' and notification_key='technician-view:00000000-0000-4000-8000-000000000101'),'technician view excludes viewer');
update cmpri_self_notification_validation.work_orders set history_actor_user_id='00000000-0000-4000-8000-000000000010' where id='00000000-0000-4000-8000-000000000100';
select set_config('cmpri.room_ranker_internal','on',true);
update cmpri_self_notification_validation.work_orders set history_actor_user_id=null where id='00000000-0000-4000-8000-000000000100';
select cmpri_self_notification_validation.emit('room-rank-change:00000000-0000-4000-8000-000000000101');
select cmpri_self_notification_validation.assert_true(not exists(select 1 from cmpri_self_notification_validation.cmpri_dashboard_notifications where recipient_user_id='00000000-0000-4000-8000-000000000010' and notification_key='room-rank-change:00000000-0000-4000-8000-000000000101'),'automatic rank recalculation retains initiating actor');
select set_config('cmpri.room_ranker_internal','',true);select set_config('cmpri.notification_actor','',true);select set_config('cmpri.notification_hotel','',true);
select cmpri_self_notification_validation.emit('room-rank-change:scheduled');
select cmpri_self_notification_validation.assert_true((select count(*)=3 from cmpri_self_notification_validation.cmpri_dashboard_notifications where notification_key='room-rank-change:scheduled'),'scheduled system event retains all recipients');
select cmpri_self_notification_validation.emit('future-event:explicit',null,'00000000-0000-4000-8000-000000000018');
select cmpri_self_notification_validation.assert_true(not exists(select 1 from cmpri_self_notification_validation.cmpri_dashboard_notifications where recipient_user_id='00000000-0000-4000-8000-000000000018' and notification_key='future-event:explicit'),'central guard covers explicit future action actors');
select cmpri_self_notification_validation.assert_true(not exists(select 1 from cmpri_self_notification_validation.cmpri_web_push_deliveries d join cmpri_self_notification_validation.cmpri_dashboard_notifications n on n.id=d.inbox_id where n.actor_user_id=n.recipient_user_id),'no self notification reaches push queue');

create table cmpri_self_notification_validation.pool_facilities(id uuid,hotel_id uuid,active boolean default true);
create table cmpri_self_notification_validation.cmpri_pool_control(hotel_id uuid,facility_id uuid,manual_closed boolean default false,manual_reason text default '',reopen_pending boolean default false,revision bigint default 1,resolved_manual_log uuid,resolved_manual_revision bigint,last_closed boolean,last_reason text,unique(hotel_id,facility_id));
create table cmpri_self_notification_validation.pool_daily_logs(id uuid default gen_random_uuid(),hotel_id uuid,pool_facility_id uuid,log_date date,manual_closure boolean default false,closure_condition boolean default false,revision bigint default 1,retest_submission jsonb,flow_rate_gpm numeric,filter_backwashed boolean,created_by uuid,updated_by uuid);
create table cmpri_self_notification_validation.cmpri_pool_control_history(id uuid,hotel_id uuid,facility_id uuid,actor_id uuid,action text,request jsonb,before_state jsonb,after_state jsonb,recorded_at timestamptz default clock_timestamp());
create function cmpri_self_notification_validation.cmpri_pool_clock() returns timestamptz language sql as $$select now()$$;
create function cmpri_self_notification_validation.cmpri_pool_test_passes(l cmpri_self_notification_validation.pool_daily_logs) returns boolean language sql as $$select true$$;
create function cmpri_self_notification_validation.cmpri_pool_snapshot(h uuid,f uuid) returns jsonb language sql as $$select jsonb_build_object('revision',revision,'hours_closed',false,'manual_closed',manual_closed) from cmpri_self_notification_validation.cmpri_pool_control where hotel_id=h and facility_id=f$$;
create function cmpri_self_notification_validation.cmpri_pool_reconcile(p_hotel uuid,p_facility uuid,p_new_event boolean default false) returns jsonb language plpgsql as $$declare result jsonb;begin result=cmpri_self_notification_validation.cmpri_pool_snapshot(p_hotel,p_facility);if p_new_event then perform cmpri_self_notification_validation.emit('pool-closed:status:'||p_facility::text||':'||(result->>'revision'));end if;return result;end$$;
__POOL_ACTION__;
__POOL_LOG__;
